<script setup lang="ts">
import { computed, onMounted } from 'vue'
import { RouterLink } from 'vue-router'
import { Building2, Clock3, CheckCircle2, MessageSquare, Plus, ArrowRight, ShieldCheck } from '@lucide/vue'
import AppSidebar from '@/components/layout/AppSidebar.vue'
import { allBrokerListings, loadBrokerListings } from '@/stores/brokerListings'
import { allBrokerInquiries, loadBrokerInquiries } from '@/stores/brokerInquiries'
import { formatBrokerPrice } from '@/data/broker/brokerListings'
onMounted(() => Promise.all([loadBrokerListings(), loadBrokerInquiries()]))

const counts = computed(() => [
  { label:'Total Listings', count:allBrokerListings.value.length, icon:Building2 },
  { label:'Approved Listings', count:allBrokerListings.value.filter(x=>x.status==='Approved').length, icon:CheckCircle2 },
  { label:'Pending Approval', count:allBrokerListings.value.filter(x=>x.status==='Pending').length, icon:Clock3 },
  { label:'Total Inquiries', count:allBrokerInquiries.value.length, icon:MessageSquare }
])
const recent = computed(() => [...allBrokerListings.value].sort((a,b)=>b.dateCreated.localeCompare(a.dateCreated)||b.id-a.id).slice(0,4))
</script>
<template>
  <AppSidebar role="broker"><main class="broker-page">
    <header class="page-header"><div><span class="eyebrow">BROKER WORKSPACE</span><h1>Dashboard Overview</h1><p>Manage represented properties, inquiries, and your broker verification.</p></div><RouterLink to="/broker/listings/create" class="primary-link"><Plus :size="18"/> Add Listing</RouterLink></header>
    <div class="demo-notice">Your listings, inquiries, and verification status are stored in the application database.</div>
    <section class="stats-grid"><article v-for="item in counts" :key="item.label" class="stat-card"><div class="stat-header"><span>{{ item.label }}</span><component :is="item.icon" :size="21"/></div><strong>{{ item.count }}</strong></article></section>
    <section class="verification"><ShieldCheck :size="25"/><div><h2>Broker Verification</h2><p>Submit your license details and wait for administrator review.</p></div><RouterLink to="/broker/profile">Manage verification</RouterLink></section>
    <div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Recent Listings</h2><p>Your latest broker-managed properties</p></div><RouterLink to="/broker/listings">View All →</RouterLink></div>
      <div v-if="recent.length===0" class="empty"><Building2 :size="36"/><h3>No Listings Yet</h3><p>Create your first listing to see it here.</p><RouterLink to="/broker/listings/create" class="primary-link"><Plus :size="17"/> Add Your First Listing</RouterLink></div>
      <RouterLink v-for="item in recent" :key="item.id" :to="`/broker/listings/${item.id}`" class="recent-row"><span class="thumb"><img v-if="item.images[0]" :src="item.images[0]" :alt="item.title"/><Building2 v-else :size="22"/></span><span class="recent-info"><strong>{{ item.title }}</strong><small>{{ item.location || 'Location not specified' }}</small><small>{{ item.price>0 ? formatBrokerPrice(item.price) : 'Price not specified' }}</small></span><span class="status" :class="item.status.toLowerCase()">{{ item.status }}</span></RouterLink>
    </section><aside class="panel"><div class="panel-heading"><div><h2>Quick Actions</h2><p>Navigate your broker workspace</p></div></div><div class="quick-actions"><RouterLink v-for="action in [{title:'Add Listing',description:'Create a commercial listing',path:'/broker/listings/create'},{title:'Manage Listings',description:'Review all your properties',path:'/broker/listings'},{title:'View Inquiries',description:'Review interested customers',path:'/broker/inquiries'},{title:'Broker Profile',description:'Verification and account information',path:'/broker/profile'}]" :key="action.path" :to="action.path" class="quick-link"><span><strong>{{ action.title }}</strong><small>{{ action.description }}</small></span><ArrowRight :size="18"/></RouterLink></div></aside></div>
  </main></AppSidebar>
</template>
